export function parseReportFalseTicketInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> & InstructionWithAccounts<TAccountMetas> & InstructionWithData<ReadonlyUint8Array>,
): ParsedReportFalseTicketInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 9) {
    throw new SolanaError(SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS, {
      actualAccountMetas: instruction.accounts.length,
      expectedAccountMetas: 9,
    })
  }
  let accountIndex = 0
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!
    accountIndex += 1
    return accountMeta
  }
  return {
    programAddress: instruction.programAddress,
    accounts: {
      reporter: getNextAccount(),
      attester: getNextAccount(),
      ledger: getNextAccount(),
      escrow: getNextAccount(),
      mint: getNextAccount(),
      device: getNextAccount(),
      lock: getNextAccount(),
      instructions: getNextAccount(),
      tokenProgram: getNextAccount(),
    },
    data: getReportFalseTicketInstructionDataDecoder().decode(instruction.data),
  }
}
